/**
 * @name Command injection in BeautifulSoup
 * @description Using os.system, subprocess, or similar with untrusted input can lead to command injection
 * @kind path-problem
 * @problem.severity error
 * @id py/command-injection
 * @tags security
 *        external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module CommandInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // os.system calls
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("os").getMember("system").getACall() and
      sink = call.getArg(0)
    ) or
    // subprocess.Popen calls
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("subprocess").getMember("Popen").getACall() and
      sink = call.getArg(0)
    ) or
    // subprocess.call, check_call, check_output, run
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("subprocess").getMember(["call", "check_call", "check_output", "run"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module CommandInjectionFlow = TaintTracking::Global<CommandInjectionConfig>;
import CommandInjectionFlow::PathGraph

from CommandInjectionFlow::PathNode source, CommandInjectionFlow::PathNode sink
where CommandInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Command injection from $@.", source.getNode(), "user input"

/**
 * @name Path traversal in file operations
 * @description File operations with user-controlled input could lead to path traversal
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // File open operations
    exists(DataFlow::CallCfgNode call |
      call = API::builtin("open").getACall() and
      sink = call.getArg(0)
    ) or
    // os.path operations
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("os").getMember("path").getMember(["join", "abspath", "realpath", "normpath"]).getACall() and
      sink = call.getArg(0)
    ) or
    // file operations
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("os").getMember(["open", "chdir", "remove", "unlink", "rename", "stat", "lstat", "chmod", "chown", "utime", "startfile"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Path traversal from $@.", source.getNode(), "user input"

/**
 * @name Data flow to XML parsing calls
 * @description Check if user input flows to XML parsing calls
 * @kind path-problem
 * @problem.severity error
 * @id py/xml-data-flow
 * @tags security
 *        external/cwe/cwe-611
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module XMLFlowConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for BeautifulSoup constructor calls
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("bs4").getMember("BeautifulSoup").getACall() and
      sink = call.getArg(0)
    )
  }
}

module XMLFlow = TaintTracking::Global<XMLFlowConfig>;
import XMLFlow::PathGraph

from XMLFlow::PathNode source, XMLFlow::PathNode sink
where XMLFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "User input flows to XML parsing at $@.", source.getNode(), "user input"
